mapper.select:
SELECT

FROM record_attachment
WHERE id = #{id}
  AND record_id = #{recordId}
  AND user_id = #{userId}
LIMIT 1

SELECT

FROM record_attachment
WHERE record_id = #{recordId}
  AND user_id = #{userId}
  AND status = 'AVAILABLE'
ORDER BY sort_order ASC, id ASC

SELECT COUNT(1)
FROM record_attachment
WHERE record_id = #{recordId}
  AND user_id = #{userId}
  AND type = #{type}
  AND status = 'AVAILABLE'

SELECT COALESCE(SUM(size_bytes), 0)
FROM record_attachment
WHERE record_id = #{recordId}
  AND user_id = #{userId}
  AND status = 'AVAILABLE'
